import java.util.*;

public class Main {
    static class Edge {
        int to, rev, cap, cost;
        Edge(int to, int rev, int cap, int cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }
    }

    static List<List<Edge>> graph;
    static int[] dist;
    static int[] cur;
    static boolean[] visited;
    static int S, T;
    static int n, m, k, c, d;

    static void addEdge(int from, int to, int cap, int cost) {
        graph.get(from).add(new Edge(to, graph.get(to).size(), cap, cost));
        graph.get(to).add(new Edge(from, graph.get(from).size() - 1, 0, -cost));
    }

    static boolean bfs() {
        Arrays.fill(dist, Integer.MAX_VALUE / 2);
        dist[S] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(S);
        visited[S] = true;
        while (!q.isEmpty()) {
            int u = q.poll();
            visited[u] = false;
            for (int i = 0; i < graph.get(u).size(); i++) {
                Edge e = graph.get(u).get(i);
                if (e.cap > 0 && dist[e.to] > dist[u] + e.cost) {
                    dist[e.to] = dist[u] + e.cost;
                    if (!visited[e.to]) {
                        visited[e.to] = true;
                        q.offer(e.to);
                    }
                }
            }
        }
        return dist[T] < 1e9;
    }

    static int dfs(int u, int f) {
        if (u == T) return f;
        visited[u] = true;
        for (int &i = cur[u]; i < graph.get(u).size(); i++) {
            Edge e = graph.get(u).get(i);
            if (!visited[e.to] && e.cap > 0 && dist[e.to] == dist[u] + e.cost) {
                int b = dfs(e.to, Math.min(f, e.cap));
                if (b > 0) {
                    e.cap -= b;
                    graph.get(e.to).get(e.rev).cap += b;
                    visited[u] = false;
                    return b;
                }
            }
        }
        visited[u] = false;
        return 0;
    }

    static int minCostFlow() {
        int flow = 0;
        int cost = 0;
        while (bfs()) {
            Arrays.fill(cur, 0);
            Arrays.fill(visited, false);
            while (true) {
                int f = dfs(S, Integer.MAX_VALUE);
                if (f == 0) break;
                flow += f;
                cost += f * dist[T];
                Arrays.fill(visited, false);
            }
        }
        return cost;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        k = sc.nextInt();
        c = sc.nextInt();
        d = sc.nextInt();

        int nodeCount = 2 + (n + k + 1) * n; // approximate max nodes
