        // The original: S=0, T=1. Then for i in 0..n+k, nodes: 2+i*n ... 1+(i+1)*n+? 
        // Let's compute properly:
        // For i from 0 to n+k: there are nodes for each j from 1 to n: j+1+i*n (first layer) and j+1+i*n+n (second layer) plus extra? Actually in the loop, there are jb for same i and for next i? 
        // The graph has nodes for each time step: for i=0..n+k, each time step has n nodes (positions). Also there is a copy? The code uses jb(x[j]+1+i*n, y[j]+1+i*n+n) and jb(y[j]+1+i*n, n+x[j]+1+i*n) meaning edges between layers? Wait.
        // Simpler: total nodes = (n+k+1)*2*n? But original uses indexing up to n+1+n*(n+k) as in gao(). So max node index = n+1 + n*(n+k) = n+1 + n^2 + nk. That's large but we can just use that as max id.
        // We'll compute maxIndex = n + 1 + n * (n + k) (since S=0, T=1, and nodes start at 2). Also we might need extra for safety.
        int maxNode = n + 1 + n * (n + k) + 5;
        graph = new ArrayList<>(maxNode);
        for (int i = 0; i < maxNode; i++) {
            graph.add(new ArrayList<>());
        }
        dist = new int[maxNode];
        cur = new int[maxNode];
        visited = new boolean[maxNode];

        S = 0;
        T = 1;

        // first edges from S to starting points
        for (int i = 0; i < k; i++) {
            int x = sc.nextInt();
            addEdge(S, x + 1, 1, 0);
        }

        int[] xArr = new int[m + 1];
        int[] yArr = new int[m + 1];
        for (int i = 1; i <= m; i++) {
            xArr[i] = sc.nextInt();
            yArr[i] = sc.nextInt();
        }

        // main loop over time steps i = 0..n+k
        for (int i = 0; i <= n + k; i++) {
            // edge from each node in this time step to T
            for (int j = 1; j <= n; j++) {
                int node = 2 + (i * n) + (j - 1);
                addEdge(node, T, k, 0);
            }
            if (i == n + k) break;

            // for each road (x,y)
            for (int j = 1; j <= m; j++) {
                int u = xArr[j];
                int v = yArr[j];
                // for l from k down to 0
                for (int l = k; l >= 0; l--) {
                    int cost = (l * 2 + 1) * d + c;
                    int uNode = 2 + i * n + (u - 1);
                    int vNode = 2 + (i + 1) * n + (v - 1);
                    addEdge(uNode, vNode, 1, cost);
