                    int uNode2 = 2 + (i + 1) * n + (u - 1);
                    addEdge(vNode2, uNode2, 1, cost);
                }
            }
            // for each node, edge to itself in next time step with cost c
            for (int j = 1; j <= n; j++) {
                int from = 2 + i * n + (j - 1);
                int to = 2 + (i + 1) * n + (j - 1);
                addEdge(from, to, k, c);
            }
        }

        System.out.println(minCostFlow());
        sc.close();
    }
}
